ARENA_ORIGIN = ""; const PROXY_API_KEY =
process.env.PROXY_API_KEY || ""; const ARENA_EMAIL = process.env.ARENA_EMAIL ||
""; const ARENA_PASSWORD = process.env.ARENA_PASSWORD || ""; const CHROMIUM_PATH
= process.env.CHROMIUM_PATH || "/usr/bin/chromium"; const MAX_BODY_BYTES =
Number(process.env.MAX_BODY_BYTES || 1048576); const MAX_PROMPT_CHARS =
Number(process.env.MAX_PROMPT_CHARS || 200000); const REQUEST_TIMEOUT_MS =
Number(process.env.REQUEST_TIMEOUT_MS || 300000); const MODEL_CACHE_MS =
Number(process.env.MODEL_CACHE_MS || 300000); const MAX_CONCURRENT_REQUESTS =
Number(process.env.MAX_CONCURRENT_REQUESTS || 1);

