error.status : 502; const type = error instanceof HttpError ? error.type :
"upstream_error"; const message = error instanceof Error ? error.message :
"Request failed"; if (res.headersSent) { res.end(); return; } json(res, status,
{ error: { message, type, param: null, code: null } }); }

function requireProxyKey(req) { if (!PROXY_API_KEY) throw new HttpError(503,
"Proxy API key is not configured", "configuration_error"); const authorization =
req.headers.authorization || ""; const token = authorization.startsWith("Bearer
") ? authorization.slice(7).trim() : ""; if (!token || token !== PROXY_API_KEY)
throw new HttpError(401, "Invalid API key", "authentication_error"); }

function requireArenaCredentials() { if (!ARENA_EMAIL || !ARENA_PASSWORD) throw
new HttpError(503, "Arena credentials are not configured",
"configuration_error"); }

async function closeBrowser() { if (browser) { await browser.close().catch(() =>
undefined); } browser = null; context = null; authPage = null; modelCache = {
expiresAt: 0, models: [] }; }

async function ensureBrowser() { requireArenaCredentials(); if (browser &&
browser.isConnected()) return browser; await closeBrowser(); try { browser =
await chromium.launch({ executablePath: CHROMIUM_PATH, headless: true, args:
["--no-sandbox", "--disable-dev-shm-usage", "--disable-gpu",
"--disable-blink-features=AutomationControlled"] }); context = await
browser.newContext({ viewport: { width: 1440, height: 1000 }, userAgent:
"Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko)
Chrome/140.0.0.0 Safari/537.36" }); authPage = await context.newPage(); await
authenticate(authPage); return browser; } catch (error) { await closeBrowser();
if (error instanceof HttpError) throw error; throw new HttpError(502, Arena
browser relay initialization failed: ${error.message}, "upstream_error"); } }

async function authenticate(page) { await page.goto(${ARENA_ORIGIN}/, {
waitUntil: "domcontentloaded", timeout: REQUEST_TIMEOUT_MS }); const result =
await page.evaluate(async ({ email, password }) => { const response = await
fetch("/nextjs-api/sign-in/email", { method: "POST", credentials: "include",
headers: { "Content-Type": "application/json" }, body: JSON.stringify({ email,
password, shouldLinkHistory: false, marketingConsent: false }) }); const text =
await response.text(); let data = null; try { data = JSON.parse(text); } catch
{} return { status: response.status, ok: response.ok, data }; }, { email:
ARENA_EMAIL, password: ARENA_PASSWORD }); if (!result.ok ||
!result.data?.success) { throw new HttpError(401, result.data?.error || Arena
login failed with HTTP ${result.status}, "upstream_authentication_error"); }
const me = await page.evaluate(async () => { const response = await
fetch("/api/me", { credentials: "include" }); return { status: response.status,
data: response.ok ? await response.json() : null }; }); if (me.status !== 200 ||
!me.data?.user) throw new HttpError(401, "Arena login did not create an
authenticated session", "upstream_authentication_error"); }

async function arenaPage() { await ensureBrowser(); const page = await
context.newPage(); page.setDefaultTimeout(REQUEST_TIMEOUT_MS); return page; }

async function loadModels(force = false) { if (!force && modelCache.expiresAt >
Date.now() && modelCache.models.length) return modelCache.models; await
ensureBrowser(); const result = await authPage.evaluate(async () => { const
response = await fetch("/nextjs-api/model-catalog", { credentials: "include" });
const text = await response.text(); return { status: response.status, text };
}); if (result.status === 401 || result.status === 403) { await
authenticate(authPage); return loadModels(true); } if (result.status !== 200)
throw new HttpError(502, Arena model catalog returned HTTP ${result.status},
"upstream_error"); let catalog; try { catalog = JSON.parse(result.text); } catch
{ throw new HttpError(502, "Arena returned invalid model catalog JSON",
"upstream_parse_error"); } const source = Array.isArray(catalog) ?
catalog.flatMap(group => Array.isArray(group.models) ? group.models : []) : [];
const models = []; const ids = new Set(); for (const item of source) { if (!item
|| typeof item.id !== "string" || !item.userSelectable) continue; if
(ids.has(item.id)) continue; ids.add(item.id); models.push({ id: item.id, name:
item.name || item.publicName || item.displayName || item.id, publicName:
item.name || item.publicName || item.displayName || item.id, displayName:
item.publicName || item.displayName || item.name || item.id, organization:
item.organization || "arena", provider: item.provider || "arena", capabilities:
item.capabilities || {} }); } if (!models.length) throw new HttpError(502,
"Arena returned no user-selectable models", "upstream_parse_error"); modelCache
= { expiresAt: Date.now() + MODEL_CACHE_MS, models }; return models; }

function resolveModel(models, requested) { const value = String(requested ||
"").trim().toLowerCase(); if (!value) throw new HttpError(400, "model is
required", "invalid_request_error"); const exact = models.find(model =>
[model.id, model.name, model.publicName, model.displayName].some(candidate =>
String(candidate).toLowerCase() === value)); if (exact) return exact; const
partial = models.filter(model => [model.name, model.publicName,
model.displayName].some(candidate =>
String(candidate).toLowerCase().includes(value))); if (partial.length === 1)
return partial[0]; throw new HttpError(404, Model not found in Arena model
catalog: ${requested}, "model_not_found"); }

function contentToText(content) { if (typeof content === "string") return
content; if (!Array.isArray(content)) return ""; return content.map(part => { if
(typeof part === "string") return part; if (part && typeof part.text ===
"string") return part.text; if (part && typeof part.content === "string") return
part.content; return ""; }).join(""); }

function messagesToPrompt(messages) { if (!Array.isArray(messages) ||
!messages.length) throw new HttpError(400, "messages must contain at least one
message", "invalid_request_error"); const text = messages.map(message => { if
(!message || typeof message !== "object") return ""; const role = typeof
message.role === "string" ? message.role : "user"; const content =
contentToText(message.content); return messages.length === 1 && role === "user"
? content : ${role}:\n${content}; }).filter(Boolean).join("\n\n").trim(); if
(!text) throw new HttpError(400, "messages must contain text",
"invalid_request_error"); if (text.length > MAX_PROMPT_CHARS) throw new
HttpError(413, "Prompt exceeds the configured size limit",
"invalid_request_error"); return text; }

function uuidv7() { const timestamp = Date.now().toString(16).padStart(12, "0");
const bytes = cryptoRandomHex(9); return
${timestamp.slice(0, 8)}-${timestamp.slice(8)}-7${bytes.slice(0, 3)}-8${bytes.slice(3, 6)}-${bytes.slice(6, 18)};
}

function cryptoRandomHex(length) { const bytes = new Uint8Array(length);
globalThis.crypto.getRandomValues(bytes); return [...bytes].map(value =>
value.toString(16).padStart(2, "0")).join(""); }

function extractAssistantText(value, model, prompt) { const text = String(value
|| "").trim(); if (!text) return ""; if (/something went wrong|generation
failed|failed to generate/i.test(text)) throw new HttpError(502, text,
"upstream_generation_error"); const modelNames = [model.publicName,
model.displayName, model.name].filter(Boolean).map(String); let start = -1; let
selectedName = ""; for (const name of modelNames) { const position =
text.indexOf(name); if (position >= 0 && (start < 0 || position < start)) {
start = position; selectedName = name; } } if (start < 0) return text; start +=
selectedName.length; const promptMarker = \n\n${prompt}\n\n; const promptEnd =
text.indexOf(promptMarker, start); const footerEnd = text.indexOf("\n\nInputs
are processed", start); const endCandidates = [promptEnd,
footerEnd].filter(position => position >= 0); const end = endCandidates.length ?
Math.min(...endCandidates) : text.length; return text.slice(start, end).trim();
}

async function generateWithArena(model, prompt) { const page = await
arenaPage(); const timeout = setTimeout(() => page.close().catch(() =>
undefined), REQUEST_TIMEOUT_MS + 5000); try { await
page.goto(${ARENA_ORIGIN}/text/direct?model_a=${encodeURIComponent(model.name)},
{ waitUntil: "domcontentloaded", timeout: REQUEST_TIMEOUT_MS }); const input =
page.locator('textarea[placeholder="Ask anything…"], textarea[placeholder="Ask
followup…"]').first(); await input.waitFor({ state: "visible", timeout:
REQUEST_TIMEOUT_MS }); await input.fill(prompt); await input.press("Enter");
await page.waitForTimeout(10000); await page.waitForFunction(({ prompt:
expectedPrompt, modelName }) => { const body = document.body?.innerText || "";
const promptPosition = body.indexOf(expectedPrompt); const modelPosition =
body.indexOf(modelName, promptPosition + expectedPrompt.length); if (/something
went wrong|generation failed|failed to generate/i.test(body)) return true;
return promptPosition >= 0 && modelPosition >= 0 &&
!body.includes("Generating..."); }, { prompt, modelName: model.publicName }, {
timeout: REQUEST_TIMEOUT_MS }); const texts = await
page.locator('main[role="presentation"]').allInnerTexts(); const bodyText =
await page.locator("body").innerText(); if (/security verification|protected by
recaptcha|please complete this quick security check/i.test(bodyText)) throw new
HttpError(403, "Arena requires an interactive reCAPTCHA security verification
before generation", "upstream_captcha_required"); if (/something went
wrong|generation failed|failed to generate/i.test(bodyText)) throw new
HttpError(502, "Arena generation failed", "upstream_generation_error"); const
candidates = [...texts, bodyText].map(text => text.trim()).filter(text =>
text.includes(model.publicName) || text.includes(model.displayName) ||
text.includes(model.name)); const result = extractAssistantText(candidates[0] ||
bodyText, model, prompt); if (!result) throw new HttpError(502, "Arena returned
an empty assistant response", "upstream_parse_error"); return result; } catch
(error) { if (error instanceof HttpError) throw error; if (error?.name ===
"TimeoutError") throw new HttpError(504, "Arena did not return a response before
the timeout", "upstream_timeout"); throw new HttpError(502, Arena generation
failed: ${error.message}, "upstream_generation_error"); } finally {
clearTimeout(timeout); await page.close().catch(() => undefined); } }

function approximateTokens(value) { return Math.max(1,
Math.ceil(String(value).length / 4)); }

function completionResponse(model, prompt, content) { const promptTokens =
approximateTokens(prompt); const completionTokens = approximateTokens(content);
return { id: chatcmpl-${randomUUID().replaceAll("-", "")}, object:
"chat.completion", created: Math.floor(Date.now() / 1000), model:
model.publicName, choices: [{ index: 0, message: { role: "assistant", content },
finish_reason: "stop" }], usage: { prompt_tokens: promptTokens,
completion_tokens: completionTokens, total_tokens: promptTokens +
completionTokens } }; }

function startStream(res) { res.writeHead(200, { "Content-Type":
"text/event-stream; charset=utf-8", "Cache-Control": "no-cache", Connection:
"keep-alive", "X-Accel-Buffering": "no" }); res.write(": connected\n\n"); return
setInterval(() => res.write(": keep-alive\n\n"), 5000); }

function writeStream(res, data, heartbeat) { const chunk = { id: data.id,
object: "chat.completion.chunk", created: data.created, model: data.model,
choices: [{ index: 0, delta: { role: "assistant", content:
data.choices[0].message.content }, finish_reason: null }] }; res.write(data:
${JSON.stringify(chunk)}\n\n); res.write(data: ${JSON.stringify({ id: data.id,
object: "chat.completion.chunk", created: data.created, model: data.model,
choices: [{ index: 0, delta: {}, finish_reason: "stop" }] })}\n\n);
clearInterval(heartbeat); res.end("data: [DONE]\n\n"); }

function writeStreamError(res, error, heartbeat) { clearInterval(heartbeat);
const status = error instanceof HttpError ? error.status : 502; const type =
error instanceof HttpError ? error.type : "upstream_error"; const message =
error instanceof Error ? error.message : "Request failed"; res.write(data:
${JSON.stringify({ error: { message, type, code: String(status) } })}\n\n);
res.end("data: [DONE]\n\n"); }

async function readBody(req) { const chunks = []; let size = 0; for await (const
chunk of req) { size += chunk.length; if (size > MAX_BODY_BYTES) throw new
HttpError(413, "Request body exceeds the configured size limit",
"invalid_request_error"); chunks.push(chunk); } if (!chunks.length) throw new
HttpError(400, "Request body is required", "invalid_request_error"); try {
return JSON.parse(Buffer.concat(chunks).toString("utf8")); } catch { throw new
HttpError(400, "Request body must be valid JSON", "invalid_request_error"); } }

function validatePayload(payload) { if (!payload || typeof payload !== "object"
|| Array.isArray(payload)) throw new HttpError(400, "Request body must be a JSON
object", "invalid_request_error"); return { stream: payload.stream === true }; }

async function runQueued(task) { const run = queue.then(async () => { if
(activeRequests >= MAX_CONCURRENT_REQUESTS) throw new HttpError(429, "Proxy
concurrency limit reached", "rate_limit_error"); activeRequests += 1; try {
return await task(); } finally { activeRequests -= 1; } }); queue = run.catch(()
=> undefined); return run; }

async function handleCompletion(req, res) { requireProxyKey(req); const payload
= await readBody(req); const options = validatePayload(payload); const execute =
() => runQueued(async () => { const prompt = messagesToPrompt(payload.messages);
const models = await loadModels(); const model = resolveModel(models,
payload.model); const content = await generateWithArena(model, prompt); return
completionResponse(model, prompt, content); }); if (!options.stream) { const
result = await execute(); json(res, 200, result); return; } const heartbeat =
startStream(res); try { const result = await execute(); writeStream(res, result,
heartbeat); } catch (error) { writeStreamError(res, error, heartbeat); } }

async function handleModels(req, res) { requireProxyKey(req); const models =
await loadModels(); json(res, 200, { object: "list", data: models.map(model =>
({ id: model.name, object: "model", created: 0, owned_by:
arena-${model.organization}, name: model.displayName, arena_id: model.id })) });
}

function handleHealth(req, res) { json(res, 200, { status: "ok", service:
"arena-personal-proxy", backend: "arena.ai", browser_relay: true }); }

async function route(req, res) { const url = new URL(req.url || "/",
 || "localhost"}); if (req.method === "GET" &&
(url.pathname === "/" || url.pathname === "/healthz")) return handleHealth(req,
res); if (req.method === "GET" && url.pathname === "/manus-routes.json") return
json(res, 200, { routes: [{ path: "/", title: "Arena Personal Proxy" }, { path:
"/healthz", title: "Health" }, { path: "/v1/models", title: "Models" }, { path:
"/v1/chat/completions", title: "Chat Completions" }] }); if (req.method ===
"GET" && url.pathname === "/v1/models") return handleModels(req, res); if
(req.method === "POST" && url.pathname === "/v1/chat/completions") return
handleCompletion(req, res); throw new HttpError(404, "Route not found",
"invalid_request_error"); }

const server = http.createServer(async (req, res) => { try { await route(req,
res); } catch (error) { openAiError(res, error); } });

server.keepAliveTimeout = 65000; server.headersTimeout = REQUEST_TIMEOUT_MS
+ 15000; server.requestTimeout = REQUEST_TIMEOUT_MS + 15000;

process.on("SIGTERM", async () => { await closeBrowser(); server.close(() =>
process.exit(0)); }); process.on("SIGINT", async () => { await closeBrowser();
server.close(() => process.exit(0)); });

server.listen(PORT, HOST);

